The program reads the input line by line and runs only lines of the form `name <- expression;`. Comments, blank lines and any surrounding prose are ignored.

Each expression is evaluated by a small hand-written parser rather than `eval`. It handles integers, variable names, parentheses, `+`, `-`, `*` and `mod`. Variables are printed in the required order, followed by `TMP`.

```python
import re
import sys

def tokenize(s):
    return re.findall(r'\d+|[A-Za-z_]\w*|[()+\-*]', s)

def evaluate(expr, env):
    tokens = tokenize(expr)
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def take():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = take()
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', 'mod'):
            op = take()
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                val = val % rhs
        return val

    def parse_factor():
        t = take()
        if t == '(':
            v = parse_expr()
            take()  # ')'
            return v
        if t == '-':
            return -parse_factor()
        if t.isdigit():
            return int(t)
        return env.get(t, 0)

    return parse_expr()

def main():
    text = sys.stdin.read()
    env = {}
    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;\s*$')
    for line in text.splitlines():
        line = line.split('//', 1)[0]
        m = assign_re.match(line)
        if not m:
            continue
        name, expr = m.group(1), m.group(2)
        env[name] = evaluate(expr, env)

    order = list("abcdefghijklmnop") + ["TMP"]
    parts = ["%s ?= %s;" % (v, env.get(v, 0)) for v in order]
    print(" ".join(parts))

if __name__ == "__main__":
    main()
```
